import {
  idOf,
  likeLiteralOf,
  metadataOf,
  optionalIdOf,
  orNull,
  requiredOf,
  sameNameOf,
  sortedByName,
  withoutNil
} from '../core/params.js'
import { getEditUrl, webHostOf } from '../utils/urls.js'

/**
 * @typedef {import('../core/params.js').Entity} Entity
 * @typedef {import('../core/params.js').Model} Model
 * @typedef {import('../core/params.js').RequestOptions} RequestOptions
 * @typedef {import('../core/params.js').TransferOptions} TransferOptions
 */

const idKey = id => (id ? String(id).toLowerCase() : null)

export const editApi = http => {
  // Before creating an edit, Zou looks for the same name in the same
  // episode, or outside any episode: the lookup keeps that parent.
  const editByName = async (project, name, episode, signal) => {
    const episodeId = optionalIdOf(episode)
    const entries = await orNull(
      http.fetchAll(
        'edits/all',
        { project_id: idOf(project), name: likeLiteralOf(name) },
        { signal }
      )
    )
    const inEpisode = entry => idKey(entry.parent_id) === idKey(episodeId)
    return sameNameOf(
      Array.isArray(entries) ? entries.filter(inEpisode) : [],
      name
    )
  }

  // A plain get, not fetchOne: a missing edit must raise instead of giving
  // a broken URL.
  const readEdit = (edit, signal) =>
    http.get(`data/edits/${idOf(edit)}`, {}, { signal })

  // Edits are saved through the entity route.
  const saveEdit = (edit, signal) =>
    http.update('entities', idOf(edit), edit, { signal })

  // Kitsu pseudo-episodes are not ids: 'main' keeps the edits out of any
  // episode, 'all' does not filter, so it is dropped as Kitsu does.
  const episodeFilterOf = episode => {
    const id = episode && typeof episode === 'object' ? episode.id : episode
    if (id === 'main') return id
    return id === 'all' ? null : optionalIdOf(episode)
  }

  return {
    /**
     * @param {Model} edit
     * @param {RequestOptions} [options]
     * @returns {Promise<Entity|null>} The edit, null when it does not exist.
     */
    getEdit: async (edit, { signal } = {}) =>
      http.fetchOne('edits', idOf(edit), { signal }),

    /**
     * @param {Model} project
     * @param {string} editName
     * @param {{episode?: Model, signal?: AbortSignal}} [options] With an
     *   episode, the lookup is scoped to it. Without one, only an edit of the
     *   project outside any episode matches.
     * @returns {Promise<Entity|null>} The edit with that name (the case
     *   ignored, an exact match first), null when there is none.
     */
    getEditByName: async (project, editName, { episode, signal } = {}) =>
      editByName(project, editName, episode, signal),

    /**
     * @param {Model} edit
     * @param {RequestOptions} [options]
     * @returns {Promise<string>} URL of the edit page in the Kitsu web app.
     */
    getEditUrl: async (edit, { signal } = {}) =>
      getEditUrl(webHostOf(http.host), await readEdit(edit, signal)),

    /**
     * @param {Model} project
     * @param {RequestOptions} [options]
     * @returns {Promise<Entity[]>} The edits of the project, sorted by name.
     */
    allEditsForProject: async (project, { signal } = {}) =>
      http
        .fetchAll(`projects/${idOf(project)}/edits`, {}, { signal })
        .then(sortedByName),

    /**
     * @param {Model} project
     * @param {{episode?: Model, signal?: AbortSignal}} [options] episode keeps
     *   the edits of that episode: an episode or its id. The pseudo-episodes
     *   of Kitsu are accepted too, as a string or as an id: 'main' keeps the
     *   edits out of any episode, 'all' does not filter.
     * @returns {Promise<Entity[]>} The edits of the project, each with its
     *   tasks.
     */
    allEditsWithTasks: async (project, { episode, signal } = {}) =>
      http.get(
        'data/edits/with-tasks',
        { project_id: idOf(project), episode_id: episodeFilterOf(episode) },
        { signal }
      ),

    /**
     * @param {Model} edit
     * @param {RequestOptions} [options]
     * @returns {Promise<Entity[]>} The data history of the edit. Zou records
     *   versions for the shots only: the list of an edit stays empty.
     */
    allVersionsForEdit: async (edit, { signal } = {}) =>
      http.get(`data/edits/${idOf(edit)}/versions`, {}, { signal }),

    /**
     * @param {Model} edit
     * @param {RequestOptions} [options]
     * @returns {Promise<Record<string, Entity[]>>} The preview files of the
     *   edit: task type ids as keys, revisions as values.
     */
    allPreviewsForEdit: async (edit, { signal } = {}) =>
      http.fetchAll(`edits/${idOf(edit)}/preview-files`, {}, { signal }),

    /**
     * Create an edit, unless the episode, or the project outside any episode,
     * already has one with that name, as getEditByName finds it: the
     * existing edit is then returned.
     * @param {Model} project
     * @param {string} name
     * @param {{
     *   description?: string,
     *   data?: object,
     *   episode?: Model,
     *   signal?: AbortSignal
     * }} [options] data is a free field for metadata of any kind.
     * @returns {Promise<Entity>} The created or existing edit.
     */
    newEdit: async (
      project,
      name,
      { description, data = {}, episode, signal } = {}
    ) => {
      const body = {
        name,
        data,
        ...withoutNil({
          episode_id: optionalIdOf(episode),
          description
        })
      }
      const path = `data/projects/${idOf(project)}/edits`
      const existing = await editByName(project, name, episode, signal)
      return existing || http.post(path, body, { signal })
    },

    /**
     * Import the edits of a CSV file into the project.
     * @param {Model} project
     * @param {Blob} csvFile The CSV data, as a Blob or a File.
     * @param {TransferOptions & {update?: boolean}} [options] update also
     *   updates the edits that already exist.
     * @returns {Promise<Entity[]>} The edit of each imported row: created,
     *   updated or left as it was. Each row is saved on its own: a failing
     *   row rejects with a ParameterError whose body gives its line_number
     *   and the count of imported_rows, which stay imported.
     */
    importEditsWithCsv: async (
      project,
      csvFile,
      { update = false, fileName, onProgress, signal } = {}
    ) =>
      http.upload(`import/csv/projects/${idOf(project)}/edits`, {
        file: requiredOf('csvFile', csvFile),
        query: { update: update ? true : null },
        fileName,
        onProgress,
        signal
      }),

    /**
     * An edit with tasks is only marked as canceled, unless forced.
     * @param {Model} edit
     * @param {{force?: boolean, signal?: AbortSignal}} [options] force deletes
     *   the edit even when tasks are linked to it.
     * @returns {Promise<null>}
     */
    removeEdit: async (edit, { force = false, signal } = {}) =>
      http.remove(
        'edits',
        idOf(edit),
        { force: force ? true : null },
        { signal }
      ),

    /**
     * Save the edit. Zou merges the given metadata into the stored ones: a
     * key left out keeps its value, a key set to null is stored as null.
     * @param {Entity} edit
     * @param {RequestOptions} [options]
     * @returns {Promise<Entity>} The updated edit.
     */
    updateEdit: async (edit, { signal } = {}) => saveEdit(edit, signal),

    /**
     * Update the edit metadata. Keys that are not given are left unchanged.
     * @param {Model} edit
     * @param {object} [data]
     * @param {RequestOptions} [options]
     * @returns {Promise<Entity>} The updated edit.
     */
    updateEditData: async (edit, data = {}, { signal } = {}) =>
      // Only the given keys: Zou merges them into the stored metadata.
      http.update(
        'entities',
        idOf(edit),
        { data: { ...metadataOf(data) } },
        { signal }
      )
  }
}
